def recovery_policy(executor):
    if executor.status is not Status.FAILURE:
        raise ValueError('Polityka wymaga statusu FAILURE')
    if executor.failure_reason == 'cancelled':
        return {'mode': 'stopped', 'plan': None, 'cost': None}
    if executor.can_retry:
        return {'mode': 'retry', 'plan': [executor.action], 'cost': None}
    plan, cost = solve(executor.state)
    if plan is None:
        return {'mode': 'blocked', 'plan': None, 'cost': None}
    return {'mode': 'replan', 'plan': plan, 'cost': cost}
